window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9752ee6dd3a401ab"]={"versions": [{"id": "FIG-9752ee6dd3a401ab", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Architektonisches Schichtenmodell / BSW-Komponentendiagramm (AUTOSAR Classic Platform, Schichtenarchitektur gemäß ISO/OSI-Referenzmodell-Anlehnung).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung der Einbettung des Transportprotokoll-Moduls <code>J1939Tp</code> (<em>SAE J1939 Transport Layer</em>) in den AUTOSAR-Kommunikationsstack. Es illustriert die parallele Koexistenz von <code>J1939Tp</code> und <code>CanTp</code> unterhalb des <code>PduR</code> (<em>PDU Router</em>) sowie die vertikale PDU-/SDU-Transformation zwischen <em>Communication Services</em> (Services Layer) und <em>Communication Interfaces</em> (ECU Abstraction Layer).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten und Module</p>\n<ul class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n<li><strong>AUTOSAR COM (<code>Com</code>):</strong> Signalorientierte Kommunikationsschicht für Applikationssignale; Schnittstelle zum RTE.</li>\n<li><strong>Diagnostic Communication Manager (<code>Dcm</code>):</strong> Diagnosedienst-Verarbeitung (z. B. UDS via ISO 14229 / SAE J1939-73 Diagnostic Messages).</li>\n<li><strong>PDU Router (<code>PduR</code>):</strong> Zentraler statischer Router für I-PDUs. Entkoppelt obere Schichten von busspezifischen TP- und IF-Modulen.</li>\n<li><strong><code>J1939Tp</code>:</strong> Segmentierungs-/Reassemblierungsmodul für Nutzlasten bis 1785 Bytes gemäß SAE J1939-21 (BAM – <em>Broadcast Announce Message</em> und CMDT – <em>Connection Mode Data Transfer</em> via RTS/CTS).</li>\n<li><strong><code>CanTp</code>:</strong> Standardisiertes ISO 15765-2 Transportprotokoll für segmentierte CAN-Kommunikation.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Interfaces (ECU Abstraction Layer):</strong></li>\n<li><strong>CAN Interface (<code>CanIf</code>):</strong> Hardware-Abstraktionsschicht für CAN-Controller und CAN-Transceiver; stellt unsegmentierten PDU-Zugriff bereit.</li>\n</ul>\n<p class=\"fig-p\">#### Datenstrukturen und Schnittstellenbeziehungen</p>\n<ul class=\"fig-list\">\n<li><strong>PDU-Typen & Transformationen:</strong></li>\n<li>*<em>I-PDU (</em>Interaction Layer PDU<em>):</em>*</li>\n<li>Bidirektional zwischen <code>Com</code>/<code>Dcm</code> und <code>PduR</code>.</li>\n<li>Unsegmentierter Direktpfad: Bidirektional zwischen <code>PduR</code> und <code>CanIf</code> (Payload $\\le$ 8 Bytes bei Classical CAN bzw. $\\le$ 64 Bytes bei CAN FD).</li>\n<li>*<em>N-SDU (</em>Network Service Data Unit<em>):</em>*</li>\n<li>Bidirektional zwischen <code>PduR</code> und den Transport-Layern (<code>J1939Tp</code>, <code>CanTp</code>). Entspricht der unsegmentierten Nutzlast auf TP-Ebene.</li>\n<li>*<em>N-PDU (</em>Network Protocol Data Unit<em>):</em>*</li>\n<li>Bidirektional zwischen Transport-Layern (<code>J1939Tp</code>, <code>CanTp</code>) und <code>CanIf</code>. Entspricht den segmentierten Einzel-Frames (z. B. J1939 TP.DT, TP.CM_BAM, TP.CM_RTS, TP.CM_CTS).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Sende-Pfade (Tx)</p>\n<ol class=\"fig-list\">\n<li><strong>Unsegmentierter I-PDU-Pfad:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Com</code> $\\rightarrow$ <code>PduR_ComTransmit()</code> $\\rightarrow$ <code>CanIf_Transmit()</code> $\\rightarrow$ CAN-Treiber.</li>\n<li>Bestätigung asynchron über <code>CanIf_TxConfirmation()</code> $\\rightarrow$ <code>PduR_CanIfTxConfirmation()</code> $\\rightarrow$ <code>Com_TxConfirmation()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Segmentierter J1939-Pfad (N-SDU $\\rightarrow$ N-PDUs):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger via <code>Com</code> oder <code>Dcm</code>: Aufruf von <code>PduR_Transmit()</code>, Weiterleitung an <code>J1939Tp_Transmit()</code> mit Längen- und PGN-Metadaten.</li>\n<li>Verbindungsaufbau:</li>\n<li><em>Broadcast:</em> <code>J1939Tp</code> sendet TP.CM_BAM via <code>CanIf_Transmit()</code>.</li>\n<li><em>Peer-to-Peer:</em> Handshake via TP.CM_RTS / TP.CM_CTS.</li>\n<li>Datenübertragung: <code>J1939Tp</code> segmentiert die Daten in Pakete (Sequenznummer 1–255), fordert Payload asynchron sukzessive über <code>PduR_J1939TpCopyTxData()</code> an und sendet einzelne TP.DT N-PDUs an <code>CanIf</code>.</li>\n<li>Abschluss: Bei P2P Bestätigung via TP.CM_EndOfMsgACK; Rückmeldung an oberen Layer über <code>PduR_J1939TpTxConfirmation()</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Empfangs-Pfade (Rx)</p>\n<ol class=\"fig-list\">\n<li><strong>Unsegmentierter Direktempfang:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CanIf_RxIndication()</code> $\\rightarrow$ <code>PduR_CanIfRxIndication()</code> $\\rightarrow$ <code>Com_RxIndication()</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Segmentierter Empfang via <code>J1939Tp</code>:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Empfang des Initial-Frames (TP.CM_BAM oder TP.CM_RTS) via <code>CanIf_RxIndication()</code>.</li>\n<li><code>J1939Tp</code> allokiert Ressourcen und ruft <code>PduR_J1939TpStartOfReception()</code> auf (Pufferbereitstellung durch oberen Layer).</li>\n<li>Eingehende Daten-Frames (TP.DT) werden über <code>PduR_J1939TpCopyRxData()</code> in den Zielpuffer kopiert.</li>\n<li>Nach vollständiger Reassemblierung: <code>PduR_J1939TpRxIndication()</code> an <code>Com</code> bzw. <code>Dcm</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Statische Routing-Tabellen (<code>PduRRoutingPath</code>) müssen strikt zwischen Direkt-Routing (<code>PduRDestPdu</code> verweist auf <code>CanIf</code>) und TP-Routing (<code>PduRDestPdu</code> verweist auf <code>J1939Tp</code> oder <code>CanTp</code>) unterscheiden.</li>\n<li>Keine dynamische Protokoll-Umschaltung zur Laufzeit möglich.</li>\n<li><strong>Metadaten-Handhabung (J1939 PGN & Adressierung):</strong></li>\n<li><code>J1939Tp</code> arbeitet PGN-basiert (Parameter Group Number) mit dynamischer oder statischer Quell-/Zieladressbindung (SA/DA).</li>\n<li>Bei variabler Zieladressierung müssen PDUs mit <code>PduInfoType.MetaDataPtr</code> konfiguriert werden, um SA/DA/Priority zwischen <code>Com</code>/<code>Dcm</code> und <code>J1939Tp</code> transparent durch den <code>PduR</code> durchzureichen.</li>\n<li><strong>Puffer-Management & Flusssteuerung:</strong></li>\n<li>J1939 BAM erfolgt ohne Flusssteuerung (festes Inter-Frame-Timing: 50–200 ms). Der empfangende Stack (<code>PduR</code> / <code>Com</code>) muss garantieren, dass Buffer-Overruns durch rechtzeitige Bereitstellung via <code>CopyRxData</code> vermieden werden.</li>\n<li>Bei RTS/CTS (CMDT) obliegt <code>J1939Tp</code> die Handhabung der Timeouts $T_1, T_2, T_3, T_4$ und $T_r$ gemäß SAE J1939-21.</li>\n<li><strong>Koexistenzbeschränkungen:</strong></li>\n<li>Eine PDU-ID ist exakt einem Transportprotokoll (<code>J1939Tp</code> ODER <code>CanTp</code>) zugeordnet. Mischbetrieb auf demselben CAN-Kanal erfordert disjunkte CAN-Identifier-Bereiche (Standard 29-Bit Extended Identifiers für J1939).</li>\n</ul>"}, {"id": "FIG-1498953fa8b67503", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Architektonisches Schichtenmodell / BSW-Gesamtübersichtsdiagramm (AUTOSAR Classic Platform, Schichtenarchitektur von Services bis Hardware).</li>\n<li><strong>Technischer Zweck:</strong> Vollständige Darstellung des AUTOSAR CAN- und J1939-Kommunikationsstacks. Das Diagramm ordnet die Transportprotokolle <code>J1939Tp</code> und <code>CanTp</code> in das Gesamtsystem ein, das neben dem <code>PduR</code> auch Security- (<code>SecOC</code>), Multiplexing- (<code>IpduM</code>), Netzwerkmanagement- (<code>J1939Nm</code>, <code>Nm</code>), Diagnose- (<code>J1939Dcm</code>, <code>Dcm</code>, <code>Dlt</code>) und Anforderungsmanagement-Module (<code>J1939Rm</code>) sowie die Hardware-Abstraktion (inkl. <code>L-SDU Router</code>) und alternative Controller-Pfade (interner On-Chip-Controller vs. externer CAN-ASIC via SPI/DIO) umfasst.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten und Module</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services:</strong></li>\n<li><strong>Signalübertragung & Serialisierung:</strong> <code>Large Data COM</code> (<code>LdCom</code>), <code>AUTOSAR COM</code> (<code>Com</code>).</li>\n<li><strong>Diagnose & Logging:</strong> <code>Diagnostic Com. Manager</code> (<code>Dcm</code>), <code>Diagnostic Log and Trace</code> (<code>Dlt</code>), <code>J1939 Diagnostic Com. Manager</code> (<code>J1939Dcm</code>).</li>\n<li><strong>J1939-Spezifische Dienste:</strong> <code>J1939 Request Manager</code> (<code>J1939Rm</code>) zur Entgegennahme und Koordination von J1939-Requests; <code>J1939Fscp</code> (Functional Safety Communication Protocol).</li>\n<li><strong>Netzwerkmanagement & Zustandssteuerung:</strong> <code>CAN State Manager</code> (<code>CanSM</code>), <code>Generic NM Interface</code> (<code>Nm</code>), <code>J1939 NM</code> (<code>J1939Nm</code>).</li>\n<li><strong>PDU-Verarbeitung & Sicherheit:</strong> <code>Secure Onboard Communication</code> (<code>SecOC</code>), <code>IPDU Multiplexer</code> (<code>IpduM</code>), <code>PDU Router</code> (<code>PduR</code>).</li>\n<li><strong>Transportprotokolle:</strong> <code>CAN Transport Protocol</code> (<code>CanTp</code>), <code>J1939 Transport Protocol</code> (<code>J1939Tp</code>).</li>\n<li><strong>Communication Hardware Abstraction:</strong></li>\n<li><code>L-SDU Router</code>: Verteilung und Routing auf L-SDU-Ebene.</li>\n<li><code>CAN Interface</code> (<code>CanIf</code>): Zentrale Abstraktionsschicht für CAN-Frames.</li>\n<li><code>CAN Transceiver Driver</code>: Transceiver-Steuerung.</li>\n<li><code>Driver for ext. CAN ASIC</code>: Abstraktionstreiber für externe CAN-Controller.</li>\n<li><strong>Communication Drivers & I/O Drivers:</strong></li>\n<li><code>DIO Driver</code>: Pin- und Interrupt-Handling für externe Controller.</li>\n<li><code>SPIHandler Driver</code>: SPI-Buskommunikation zum externen CAN-ASIC.</li>\n<li><code>CAN Driver</code>: Direkter MCAL-Treiber für On-Chip-CAN-Controller.</li>\n<li><strong>Hardware:</strong></li>\n<li><code>µC</code>: Mikrocontroller mit integriertem CAN-Controller.</li>\n<li><code>External CAN Controller</code>: Separater, extern angebundener CAN-Controller.</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellenbeziehungen</p>\n<ul class=\"fig-list\">\n<li>Das Diagramm verzichtet auf gerichtete Kanten und PDU-/SDU-Typbezeichnungen (wie I-PDU, N-SDU, N-PDU). Die Beziehungen sind rein über die vertikale Schichtung und Schachtelung der BSW-Module dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Sende- und Empfangspfade (Tx/Rx)</p>\n<ol class=\"fig-list\">\n<li><strong>PDU-Routing & Services:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Daten von <code>Com</code>, <code>LdCom</code> oder Diagnosemodulen (<code>Dcm</code>, <code>J1939Dcm</code>) durchlaufen optional Vorverarbeitungsstufen (<code>SecOC</code> zur kryptografischen Absicherung, <code>IpduM</code> zum Multiplexen), bevor sie den <code>PduR</code> erreichen.</li>\n<li><code>PduR</code> verteilt I-PDUs entweder unsegmentiert oder leitet N-SDUs an die Transportprotokolle <code>J1939Tp</code> bzw. <code>CanTp</code> zur Segmentierung/Reassemblierung weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Hardware-Abstraktion & L-SDU-Routing:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pakete passieren den <code>L-SDU Router</code> und das <code>CAN Interface</code> (<code>CanIf</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweipfadige Hardware-Ansteuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Interner Pfad:</strong> <code>CanIf</code> $\\rightarrow$ <code>CAN Driver</code> $\\rightarrow$ integrierter Controller auf dem <code>µC</code>.</li>\n<li><strong>Externer Pfad:</strong> <code>CanIf</code> $\\rightarrow$ <code>Driver for ext. CAN ASIC</code> $\\rightarrow$ <code>SPIHandler Driver</code> (Payload/Registerzugriff) und <code>DIO Driver</code> (Interrupts/Status) $\\rightarrow$ <code>External CAN Controller</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Netzwerk- und Protokollmanagement:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>J1939Rm</code> fängt J1939-Request-PGNs ab und leitet Anfragen an die zuständigen Module weiter.</li>\n<li><code>J1939Nm</code> interagiert über das <code>Generic NM Interface</code> für Address Claiming und Bus-Zustandsverwaltung parallel zum <code>CanSM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Externe Controller-Architektur:</strong></li>\n<li>Der Einsatz externer CAN-ASICs bedingt eine vollständige Konfiguration des SPI- und DIO-Stacks im MCAL sowie des modulspezifischen Treibers <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>L-SDU Router:</strong></li>\n<li>Einführung des <code>L-SDU Router</code> in der Hardware-Abstraktionsschicht ermöglicht dynamisches oder alternatives Routing unterhalb der Schnittstellenmodule.</li>\n<li><strong>Erweiterte J1939-Subsystem-Konfiguration:</strong></li>\n<li>Vollständige J1939-Konformität erfordert neben <code>J1939Tp</code> die Parametrierung des <code>J1939Rm</code> (Filterung und Dispatching von PGN 59904), <code>J1939Dcm</code> (Diagnoseprotokolle DM1–DMxx) und <code>J1939Nm</code> (Address Claiming gemäß SAE J1939-81).</li>\n<li><strong>Entfall expliziter PDU-Kennzeichnungen:</strong></li>\n<li>Das Diagramm dient als architektonische Systemübersicht; detaillierte PDU-Typisierungen (I-PDU, N-SDU, N-PDU) und API-Aufrufketten sind den jeweiligen Modulspezifikationen zu entnehmen.</li>\n</ul>"}], "trans": [{"from": "FIG-9752ee6dd3a401ab", "to": "FIG-1498953fa8b67503", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Gesamtarchitektur:</strong> Ersetzung des reduzierten J1939Tp/CanTp-Fokusdiagramms durch das vollständige AUTOSAR-Kommunikationsstack-Architekturmodell.</li>\n<li><strong>Communication Services:</strong> Hinzufügung der Module <code>Large Data COM</code>, <code>Diagnostic Log and Trace</code>, <code>J1939 Diagnostic Com. Manager</code>, <code>J1939 Request Manager</code>, <code>CAN State Manager</code>, <code>Generic NM Interface</code>, <code>J1939 NM</code>, <code>J1939Fscp</code>, <code>Secure Onboard Communication</code> und <code>IPDU Multiplexer</code>.</li>\n<li><strong>Communication Hardware Abstraction:</strong> Ergänzung um <code>L-SDU Router</code>, <code>CAN Transceiver Driver</code> und <code>Driver for ext. CAN ASIC</code>.</li>\n<li><strong>Treiber- und Hardware-Ebene:</strong> Neuaufnahme von <code>I/O Drivers</code> (<code>DIO Driver</code>), <code>Communication Drivers</code> (<code>SPIHandler Driver</code>, <code>CAN Driver</code>), <code>µC</code> sowie <code>External CAN Controller</code>.</li>\n<li><strong>Schnittstellen & Datenflüsse:</strong> Vollständige Entfernung gerichteter Datenflusspfeile und PDU-/SDU-Typbeschriftungen (<code>I-PDU</code>, <code>N-SDU</code>, <code>N-PDU</code>); Übergang zu einer rein hierarchischen Block-Schachtelung.</li>\n</ul>"}]};
